const JobFieldService={async load(e,s=null){const t=await DB.getJob(e);if(!t)throw new Error("Job not found");const o=t.job||t;return{job:o,checklist:("function"==typeof DB.getChecklistForJob?await DB.getChecklistForJob(o.id,s||o.appointmentId||null):{template:null,items:[],responses:[]})||{items:[],responses:[]},issues:("function"==typeof DB.getJobIssues?await DB.getJobIssues(o.id):t.issues||[])||[]}},assess(e){const s=new Map((e.checklist.responses||[]).map(e=>[e.checklistItemId,e])),t=(e.checklist.items||[]).filter(e=>!1!==e.required&&!s.get(e.id)?.completed),o=(e.issues||[]).filter(e=>!e.resolvedAt&&"resolved"!==e.status);return{mandatoryIncomplete:t,openIssues:o,blocked:t.length>0||o.length>0}},render(e){const{job:s,checklist:t,issues:o}=e,a=new Map((t.responses||[]).map(e=>[e.checklistItemId,e])),n=o.filter(e=>!e.resolvedAt&&"resolved"!==e.status),i=s.status||s.stage;return`<section class="card card-page" aria-labelledby="job-checklist-title"><div class="flex justify-between items-center"><h2 class="section-label mb-0" id="job-checklist-title">Fitting checklist</h2><span class="badge">${(t.items||[]).filter(e=>a.get(e.id)?.completed).length}/${(t.items||[]).length}</span></div>\n      ${(t.items||[]).length?`<div class="mt-sm">${t.items.map(e=>`<label class="flex items-start gap-sm py-8"><input class="job-check-input" type="checkbox" ${a.get(e.id)?.completed?"checked":""} data-event="change" data-action="JobsFeature.setChecklistItem" data-args='${JSON.stringify([s.id,e.id,"__event__"])}'><span><strong>${Utils.escapeHtml(e.label||e.title||"Checklist item")}</strong>${!1===e.required?'<small class="block text-tertiary">Optional</small>':""}</span></label>`).join("")}</div>`:'<div class="empty-state py-md">No checklist template assigned.</div>'}\n    </section>\n    <section class="card card-page" aria-labelledby="job-issues-title"><div class="flex justify-between items-center"><h2 class="section-label mb-0" id="job-issues-title">Issues & return visits</h2><button class="btn btn-outline btn-sm" data-action="JobsFeature.openAddIssue" data-args='${JSON.stringify([s.id])}'><span class="material-symbols-rounded">add</span>Issue</button></div>\n      ${n.length?n.map(e=>`<div class="mt-sm p-sm inset-dark"><strong>${Utils.escapeHtml(e.title||e.type||"Job issue")}</strong>${e.notes?`<div class="fs-13 text-secondary mt-2">${Utils.escapeHtml(e.notes)}</div>`:""}${e.requiresReturnVisit?'<span class="badge badge-warning mt-4">Return visit needed</span>':""}<button class="btn btn-outline btn-sm mt-sm" data-action="JobsFeature.openResolveIssue" data-args='${JSON.stringify([e.id,s.id])}'>Resolve</button></div>`).join(""):'<div class="fs-13 text-secondary mt-sm">No open issues.</div>'}\n    </section>\n    <div class="flex flex-col gap-sm">${["completed","signed_off"].includes(i)?"":`<button class="btn btn-primary btn-block" data-action="JobsFeature.openCompleteJob" data-args='${JSON.stringify([s.id])}'><span class="material-symbols-rounded">task_alt</span>Complete job</button>`}${"completed"===i?`<button class="btn btn-outline btn-block" data-action="JobsFeature.openSignOff" data-args='${JSON.stringify([s.id])}'><span class="material-symbols-rounded">draw</span>Customer sign-off</button>`:""}<p class="hint">Completing a job records the operational work only. It does not mark the order or balance as paid.</p></div>`},async setChecklistItem(e,s,t){const o=!!t?.target?.checked;try{await DB.setChecklistResponse({jobId:e,checklistItemId:s,completed:o}),Toast.show(o?"Checklist item completed":"Checklist item reopened","success")}catch(e){t?.target&&(t.target.checked=!o),Toast.show("Could not update checklist","error")}},openAddIssue(e){App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Add job issue</h3><button class="btn btn-ghost btn-sm" aria-label="Close" data-action="App.closeModal"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body"><div class="form-group"><label for="job-issue-title">Issue</label><input class="input" id="job-issue-title" maxlength="160" required></div><div class="form-group"><label for="job-issue-notes">Details</label><textarea class="textarea" id="job-issue-notes" maxlength="500"></textarea></div><label class="flex items-center gap-sm mb-md"><input type="checkbox" id="job-issue-return">Return visit required</label><button class="btn btn-primary btn-block" data-action="JobsFeature.saveIssue" data-args='${JSON.stringify([e])}'>Save issue</button></div>`)},async saveIssue(e){const s=document.getElementById("job-issue-title")?.value.trim();if(!s)return Toast.show("Describe the issue","warning");await DB.addJobIssue(e,{title:s,notes:document.getElementById("job-issue-notes")?.value.trim()||"",requiresReturnVisit:!!document.getElementById("job-issue-return")?.checked,status:"open"}),App.closeModal(),Toast.show("Issue saved","success"),App.navigate("jobs",{id:e})},openResolveIssue(e,s){App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Resolve issue</h3></div><div class="sheet-body"><div class="form-group"><label for="job-issue-resolution">Resolution</label><textarea class="textarea" id="job-issue-resolution" required></textarea></div><label class="flex items-start gap-sm mb-md"><input type="checkbox" id="job-issue-resolved-confirm"><span>I confirm this issue has been resolved.</span></label><button class="btn btn-primary btn-block" data-action="JobsFeature.resolveIssue" data-args='${JSON.stringify([e,s])}'>Confirm resolution</button><button class="btn btn-outline btn-block mt-sm" data-action="App.closeModal">Cancel</button></div>`)},async resolveIssue(e,s){const t=!!document.getElementById("job-issue-resolved-confirm")?.checked,o=document.getElementById("job-issue-resolution")?.value.trim();return t?o?(await DB.resolveJobIssue(e,o,{confirmed:!0}),App.closeModal(),Toast.show("Issue resolved","success"),void App.navigate("jobs",s?{id:s}:{})):Toast.show("Add the resolution","warning"):Toast.show("Confirm the issue is resolved","warning")},async openComplete(e){const s=await this.load(e),t=this.assess(s);this.pendingJob=s.job,this.pendingCompletionBlocked=t.blocked,App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Complete job?</h3><button class="btn btn-ghost btn-sm" aria-label="Close" data-action="App.closeModal"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body">${t.mandatoryIncomplete.length?`<div class="alert alert-warning" role="alert">${t.mandatoryIncomplete.length} required checklist item${1===t.mandatoryIncomplete.length?"":"s"} incomplete.</div>`:""}${t.openIssues.length?`<div class="alert alert-warning" role="alert">${t.openIssues.length} issue${1===t.openIssues.length?"":"s"} unresolved.</div>`:""}${t.blocked?'<div class="form-group"><label for="job-complete-override">Override reason</label><textarea class="textarea" id="job-complete-override" required aria-describedby="job-override-help"></textarea><div class="hint" id="job-override-help">Required because work remains incomplete or unresolved.</div></div>':""}<label class="flex items-start gap-sm mb-md"><input type="checkbox" id="job-complete-confirm"><span>I confirm the fitting work is operationally complete. This does not record payment.</span></label><button class="btn btn-primary btn-block" data-action="JobsFeature.confirmCompleteJob" data-args='${JSON.stringify([e])}'>Confirm job complete</button><button class="btn btn-outline btn-block mt-sm" data-action="App.closeModal">Cancel</button></div>`)},async confirmComplete(e){if(!document.getElementById("job-complete-confirm")?.checked)return Toast.show("Confirm the work is complete","warning");const s=document.getElementById("job-complete-override")?.value.trim()||"";if(this.pendingCompletionBlocked&&!s)return Toast.show("Add an override reason for incomplete work or issues","warning");if(this.pendingMutations=this.pendingMutations||new Set,!this.pendingMutations.has(`complete:${e}`)){this.pendingMutations.add(`complete:${e}`);try{await DB.completeJob(e,{confirmed:!0,overrideReason:s||null,operationId:this.operationId("complete",e)}),App.closeModal(),Toast.show("Job completed — payment unchanged","success"),App.navigate("jobs",{id:e})}catch(e){Toast.show(e.message||"Could not complete job","error")}finally{this.pendingMutations.delete(`complete:${e}`)}}},openSignOff(e){App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Customer sign-off</h3></div><div class="sheet-body"><div class="form-group"><label for="job-signoff-name">Customer name</label><input class="input" id="job-signoff-name" autocomplete="name" required></div><label class="flex items-start gap-sm mb-md"><input type="checkbox" id="job-signoff-confirm"><span>The customer has reviewed the completed work and confirmed sign-off.</span></label><button class="btn btn-primary btn-block" data-action="JobsFeature.confirmSignOff" data-args='${JSON.stringify([e])}'>Record sign-off</button><button class="btn btn-outline btn-block mt-sm" data-action="App.closeModal">Cancel</button></div>`)},async confirmSignOff(e){const s=document.getElementById("job-signoff-name")?.value.trim();if(!s)return Toast.show("Enter the customer name","warning");if(!document.getElementById("job-signoff-confirm")?.checked)return Toast.show("Confirm customer sign-off","warning");if(this.pendingMutations=this.pendingMutations||new Set,!this.pendingMutations.has(`signoff:${e}`)){this.pendingMutations.add(`signoff:${e}`);try{await DB.signOffJob(e,{confirmed:!0,customerName:s,method:"advisor_recorded",operationId:this.operationId("signoff",e)}),App.closeModal(),Toast.show("Customer sign-off recorded","success"),App.navigate("jobs",{id:e})}catch(e){Toast.show(e.message||"Could not record sign-off","error")}finally{this.pendingMutations.delete(`signoff:${e}`)}}},operationId:(e,s)=>`job:${e}:${s}:${globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`}`};
